	//                               // - number: "=", ">", "<", ">=", "<="
	//                               // - stringObject: "=", "contains", "does not contain", "starts with", "ends with", "matches", "is set", "is not set"
	//                               // - numberObject: "=", ">", "<", ">=", "<="
